import{_ as i,o as a,c as e,a2 as n}from"./chunks/framework.BiXHgXAn.js";const c=JSON.parse('{"title":"Running tasks","description":"How Task finds a Taskfile, and how to run one from a subdirectory, from your home directory, from standard input or as a dry run.","frontmatter":{"title":"Running tasks","description":"How Task finds a Taskfile, and how to run one from a subdirectory, from your home directory, from standard input or as a dry run.","section":"Guide","docType":"guide","outline":"deep"},"headers":[],"relativePath":"docs/guide/running-tasks.md","filePath":"next/docs/guide/running-tasks.md"}'),t={name:"docs/guide/running-tasks.md"};function l(p,s,r,h,o,d){return a(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="running-tasks" tabindex="-1">Running tasks <a class="header-anchor" href="#running-tasks" aria-label="Permalink to &quot;Running tasks&quot;">​</a></h1><p>Run <code>task &lt;name&gt;</code> from your project to execute a task. With no name, Task runs the <code>default</code> task. Start by listing tasks, then run one:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p><code>--list</code> shows tasks with descriptions. Use <code>--list-all</code> to include tasks without descriptions; <a href="./defining-tasks#internal-tasks">internal tasks</a> remain hidden. See <a href="./defining-tasks">Defining tasks</a> to create these entries.</p><p>Pass several names, such as <code>task lint test</code>, to run them in order. Use <a href="./dependencies#limiting-how-much-runs-at-once"><code>--parallel</code></a> for independent tasks that can run concurrently. To pass values or command arguments, see <a href="./arguments">Command-line arguments</a>.</p><h2 id="dry-run-mode" tabindex="-1">Preview commands <a class="header-anchor" href="#dry-run-mode" aria-label="Permalink to &quot;Preview commands {#dry-run-mode}&quot;">​</a></h2><p>Use <code>--dry</code> (or <code>-n</code>) to print the commands Task would run:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Task still resolves templates and dynamic variables while preparing the commands. A variable declared with <code>sh</code> can therefore execute its shell command during a dry run. See <a href="./variables#when-values-are-computed">Variables</a>.</p><h2 id="running-a-taskfile-from-a-subdirectory" tabindex="-1">Run from a subdirectory <a class="header-anchor" href="#running-a-taskfile-from-a-subdirectory" aria-label="Permalink to &quot;Run from a subdirectory {#running-a-taskfile-from-a-subdirectory}&quot;">​</a></h2><p>If Task cannot find a Taskfile in the current directory, it searches parent directories. Tasks run from the directory containing that Taskfile unless <a href="./defining-tasks#task-directory">their <code>dir</code> setting</a> changes it.</p><p>Use <span><code>{{.USER_WORKING_DIR}}</code></span> when the task should act on the directory where you invoked it. In a monorepo, this lets each service use the same task to start its Docker Compose services:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  up</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{.USER_WORKING_DIR}}&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    preconditions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">test -f docker-compose.yml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">docker compose up -d</span></span></code></pre></div><p>From a service directory containing <code>docker-compose.yml</code>, run <code>task up</code>. The root Taskfile supplies the task; the service directory supplies its files.</p><h2 id="running-a-global-taskfile" tabindex="-1">Use a personal Taskfile <a class="header-anchor" href="#running-a-global-taskfile" aria-label="Permalink to &quot;Use a personal Taskfile {#running-a-global-taskfile}&quot;">​</a></h2><p>Store a Taskfile in your home directory and use <code>--global</code> (or <code>-g</code>) to call it from anywhere:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from-working-directory</span></span></code></pre></div><p>Global tasks run in your home directory by default. Set <code>dir</code> to <span><code>{{.USER_WORKING_DIR}}</code></span> when a personal utility should work on the current project:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  from-home</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pwd</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  from-working-directory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{.USER_WORKING_DIR}}&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pwd</span></span></code></pre></div><h2 id="running-a-taskfile-from-stdin" tabindex="-1">Read a Taskfile from stdin <a class="header-anchor" href="#running-a-taskfile-from-stdin" aria-label="Permalink to &quot;Read a Taskfile from stdin {#running-a-taskfile-from-stdin}&quot;">​</a></h2><p>Use <code>--taskfile -</code> (or <code>-t -</code>) to read a generated Taskfile from standard input. For example, to read an existing file through stdin:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --taskfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./Taskfile.yml</span></span></code></pre></div><p>You can also pipe the output of a Taskfile generator into <code>task --taskfile -</code>. With no task name, these commands run the generated file&#39;s <code>default</code> task.</p><h2 id="interactive-cli-application" tabindex="-1">Run a terminal app <a class="header-anchor" href="#interactive-cli-application" aria-label="Permalink to &quot;Run a terminal app {#interactive-cli-application}&quot;">​</a></h2><p>Set <code>interactive: true</code> on a task that launches a terminal application:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;3&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tasks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  edit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    interactive</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    cmds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vim my-file.txt</span></span></code></pre></div><p>Run <code>task edit</code> to open the editor. Interactive applications need direct access to the terminal; buffered or prefixed <a href="./output#output-syntax">output modes</a> and other tasks running concurrently can interfere with their input and display.</p><p>This task setting is distinct from the CLI <code>--interactive</code> option, which <a href="./required-variables#prompting-for-missing-variables-interactively">prompts for missing variables</a>.</p><h2 id="supported-file-names" tabindex="-1">Choose a file name <a class="header-anchor" href="#supported-file-names" aria-label="Permalink to &quot;Choose a file name {#supported-file-names}&quot;">​</a></h2><p>Use <code>--taskfile</code> to choose a specific file or <code>--dir</code> to run in another project:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --taskfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Taskfile.ci.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Task looks for these names in order of priority:</p><ul><li><code>Taskfile.yml</code></li><li><code>taskfile.yml</code></li><li><code>Taskfile.yaml</code></li><li><code>taskfile.yaml</code></li><li><code>Taskfile.dist.yml</code></li><li><code>taskfile.dist.yml</code></li><li><code>Taskfile.dist.yaml</code></li><li><code>taskfile.dist.yaml</code></li></ul><p>Commit a <code>.dist</code> variant if users need to supply their own <code>Taskfile.yml</code> override. The local file takes priority; add it to <code>.gitignore</code> if it should remain personal.</p>`,34)])])}const u=i(t,[["render",l]]);export{c as __pageData,u as default};
